    }

    /// İcra olunmuş rəddin nişanını silir, amma yalnız nəticə diskdədirsə: razılıq yaddaş faylına, təmizlənmiş növbə
    /// öz faylına yazılıb. Alınmasa nişan qalır və sonrakı çağırışda yenidən cəhd olunur. Yalnız SDK növbəsində çağırılır.
    private static func settleMark() {
        guard let token = appliedMark else { return }
        lock.lock()
        let store = fileStore
        let events = fileQueue
        lock.unlock()
        if let store = store, store.unsaved { return }
        if let events = events, !events.persist() { return }
        tombstone.settle(token)
        appliedMark = nil
    }

    /// Təkrar `initialize`-in sərtləşdirən seçimləri (bax `Core.restrict`).
    private static func restrict(_ options: SmartBeeOptions) {
        let consent = options.consent
        let collect = options.collectAdvertisingId
        if consent == nil, collect { return }
        let denyAnalytics = consent.map { !$0.analytics } ?? false
        let denyAds = consent.map { !$0.ads } ?? false
        // Rədd əvvəlcə çağıran axında diskə yazılır (razılıq dəyəri dəyişmir: bu məhdudiyyət saxlanmır).
        let token = recordDenial(denyAnalytics: denyAnalytics, denyAds: denyAds, consent: nil)
        let release = hold(denyAnalytics: denyAnalytics, denyAds: denyAds, holdId: denyAnalytics, newId: nil)
        let slot = RestrictLimits.slot(denyAnalytics: denyAnalytics, denyAds: denyAds)
        let limits = RestrictLimits(analytics: denyAnalytics, ads: denyAds, noAdId: !collect, token: token, releases: [slot: release])
        let entry = restrictEntry(limits)
        post(kind: kindRestrict, denies: denyAnalytics, deniesAds: denyAds, persistNow: true, discard: entry.discard, limits: limits, entry.call)
    }

    /// Məhdudiyyətlərdən gözləmə siyahısının yazısını qurur: icra olunanda (və ya atılanda) bütün qadağaları götürür.
    private static func restrictEntry(_ limits: RestrictLimits) -> Pending {
        let releases = Array(limits.releases.values)
        let done: () -> Void = {
            for item in releases { item() }
        }
        var consent: SmartBeeConsent?
        if limits.analytics || limits.ads {
            consent = SmartBeeConsent(analytics: !limits.analytics, ads: !limits.ads)
        }
        let chosen = consent
        let collect = !limits.noAdId
        let token = limits.token
        let call: (Core) -> Void = { core in
            core.restrict(consent: chosen, collectAdvertisingId: collect)
            done()
            applied(token)
        }
        return Pending(kind: kindRestrict, denies: limits.analytics, deniesAds: limits.ads, persistNow: true, call: call, discard: done, limits: limits)
    }

    /// Nüvəni yaradır və başladır. Yalnız SDK növbəsində çağırılır.
    ///
    /// Yaddaş faylları mövcuddur, amma oxunmursa (cihaz yenidən başlayıb, kilidi hələ açılmayıb) nüvə
    /// yaradılmır və heç nə yazılmır: əks halda SDK özünü ilk dəfə quraşdırılmış sayar və saxlanmış
    /// razılığın, anonim ID-nin və növbənin üstündən yazardı. Çağırışlar gözləmə siyahısında qalır,
    /// başlanğıc isə fayllar əlçatan olanda və ya tətbiq aktivləşəndə təkrar yoxlanılır.
    private static func boot(key: String, options: SmartBeeOptions, env: AppleEnv) {
        lock.lock()
        let ready = core != nil
        lock.unlock()
        if ready { return }

        let store = FileStore()
        let events = FileQueue()
        // Rədd nişanı da oxunmalıdır: oxunmursa içində icra olunmamış rədd ola bilər.
        tombstone.reload()
        if store.unreadable || events.unreadable || tombstone.unreadable {
            if options.debug { NSLog("[SmartBee] storage is not readable yet, start is postponed") }
            return
        }
        // Çağıran axında yazılmış, amma nüvədə icra olunmamış rədd (əvvəlki proses ölüb və ya nüvə hələ başlamamışdı):
        // nüvə onu heç nə göndərilməzdən əvvəl tətbiq edir.
        let saved = tombstone.current()
        let created = Core(
            key: key,
            options: options,
            store: store,
            queue: events,
            transport: URLSessionTransport(debug: options.debug),
            env: env,
            gate: consentGate,
            mark: saved.mark
        )
        created.start()
        if saved.mark != nil { applied(saved.generation) }
        events.persist()
        lock.lock()
        core = created
        fileQueue = events
        fileStore = store
        bootArgs = nil
        let queued = pending
        let dropped = droppedCalls
        pending.removeAll()
        pendingCalls = 0
        droppedCalls = 0
        lock.unlock()
        if dropped > 0 { created.note("\(dropped) calls made before initialize were dropped (limit \(maxPending))") }
        for entry in queued { entry.call(created) }
        setAnonymousId(created.anonymousId)
        events.persist()
        settleMark()
        schedule(created, events, store)
        // Konfiq sorğusu uzun çəkə bilər, ona görə nüvə dərc olunandan və növbə diskə yazılandan sonra göndərilir.
        queue.async {
            created.refreshConfig()
            setAnonymousId(created.anonymousId)
            events.persist()
        }
    }

    /// Təxirə salınmış başlanğıcı yenidən yoxlayır.
    private static func retryBoot() {
        lock.lock()
        let saved = bootArgs
        lock.unlock()
        guard let args = saved else { return }
        queue.async { boot(key: args.key, options: args.options, env: args.env) }
    }

    /// Arxa fondan qayıdışda (və ilk açılışda) bir dəfə AppOpen göndərir. Yalnız əsas axında çağırılır.
    private static func openIfNeeded() {
        if !needsOpen { return }
        needsOpen = false
        // AppOpen-in vaxtı bildirişin gəldiyi andır, nüvənin onu emal etdiyi an yox.
        post(kind: kindLifecycle, launchGate.foreground(at: clock()))
    }

    /// Nüvənin anonim ID-sini açıq keşə yazır; ID-ni dəyişən çağırış hələ gözləyirsə keşə toxunmur.
    private static func setAnonymousId(_ value: String?) {
        lock.lock()
        if idHolds == 0 { cachedAnonymousId = value }
        lock.unlock()
    }

    /// Gözləmə siyahısına əlavə edir. Yalnız `lock` altında çağırılır. Atılan çağırışların `discard` funksiyalarını
    /// qaytarır: onlar kilid buraxılandan sonra çağırılmalıdır (özləri də eyni kilidi götürür).
    private static func addPending(_ entry: Pending) -> [() -> Void] {
        var discards: [() -> Void] = []
        if entry.kind == kindCall {
            // Adi çağırışlar məhdud sayda saxlanır; atılanlar sayılır və başlanğıcda sazlama loquna yazılır.
            if pendingCalls >= maxPending {
                droppedCalls += 1
                return discards
            }
            pendingCalls += 1
            pending.append(entry)
            return discards
        }
        if entry.kind == kindRestrict, let fresh = entry.limits {
            // Təkrar `initialize` çağırışları heç vaxt atılmır, amma siyahı da böyüməməlidir: ardıcıl gələnlər bir
            // yazıda birləşdirilir (məhdudiyyətlər toplanır). Siyahı dolubsa yeni çağırış sonuncu belə yazı ilə
            // birləşdirilib sona keçirilir: bu, yalnız sərtləşdirə bilər.
            var index: Int?
            if let last = pending.last, last.kind == kindRestrict {
                index = pending.count - 1
            } else if pending.count - pendingCalls >= maxPending {
                index = pending.lastIndex(where: { $0.kind == kindRestrict })
            }
            if let index = index, let old = pending[index].limits {
                let merged = old.merging(fresh)
                pending.remove(at: index)
                pending.append(restrictEntry(merged.limits))
                discards.append(contentsOf: merged.redundant)
                return discards
            }
            pending.append(entry)
            return discards
        }
        // Razılıq, reset və həyat dövrü çağırışları heç vaxt atılmır. Siyahı böyüməsin deyə ardıcıl gələn eyni növ
        // çağırışlardan yalnız sonuncusu qalır; razılığı (analitika və ya reklam) geri alan çağırış onu yenidən verən
        // çağırışla əvəz olunmur (aradakı silinmə itməsin).
        if let last = pending.last, last.kind == entry.kind, entry.kind != kindRestrict,
           !PendingRule.keepsWithdrawal(lastDenies: last.denies, lastDeniesAds: last.deniesAds, nextDenies: entry.denies, nextDeniesAds: entry.deniesAds) {
            pending[pending.count - 1] = entry
            if let discard = last.discard { discards.append(discard) }
            return discards
        }
        if pending.count - pendingCalls >= maxPending, entry.kind != kindRestrict {
            if let index = pending.lastIndex(where: { $0.kind == entry.kind }) {
                let old = pending.remove(at: index)
                if let discard = old.discard { discards.append(discard) }
            }
        }
        pending.append(entry)
        return discards
    }

    private static func post(
        kind: Int = 0,
        denies: Bool = false,
        deniesAds: Bool = false,
        persistNow: Bool = false,
        discard: (() -> Void)? = nil,
        limits: RestrictLimits? = nil,
        droppable: Bool = false,
        _ call: @escaping (Core) -> Void
    ) {
        if isExtension {
            discard?()
            return
        }
        lock.lock()
        guard let current = core else {
            // initialize hələ bitməyib: çağırış yadda saxlanır.
            let entry = Pending(kind: kind, denies: denies, deniesAds: deniesAds, persistNow: persistNow, call: call, discard: discard, limits: limits)
            let discards = addPending(entry)
            lock.unlock()
            for item in discards { item() }
            return
        }
        let events = fileQueue
        // SDK növbəsi yavaş sorğuda ilişibsə gözləyən `track` / `screen` çağırışları hədsiz yığılmamalıdır: ən çoxu
        // `maxPending` gözləyir və dolanda ən köhnəsi atılır. Qalan çağırışlar heç vaxt atılmır; sıra dəyişmir.
        var ticket: BusyCalls.Ticket?
        var direct: ((Core) -> Void)?
        if droppable {
            ticket = busyCalls.add(call)
        } else {
            direct = call
        }
        let waiting = ticket
        let plain = direct
        lock.unlock()
        queue.async {
            var work = plain
            lock.lock()
            if let waiting = waiting { work = busyCalls.take(waiting) }
            let dropped = busyCalls.takeDropped()
            lock.unlock()
            if dropped > 0 {
                current.note("\(dropped) track / screen calls made while the SDK was busy were dropped, oldest first (limit \(maxPending))")
            }
            // Atılmış çağırış: yeri boş keçir.
            guard let run = work else { return }
            run(current)
            setAnonymousId(current.anonymousId)
            guard let events = events else { return }
            if persistNow {
                events.persist()
                // Razılıq çağırışı icra olundu və nəticə diskdədir: çağıran axında yazılmış rədd nişanı silinir.
                settleMark()
            } else {
                persistLater(events)
            }
        }
    }

    /// Növbəni diskə yazır; son yazıdan 2 saniyə keçməyibsə yazını 2 saniyə sonraya planlaşdırır ki, event başqa
    /// SDK çağırışı olmasa da ən çox ~2 saniyəyə diskdə olsun. Yalnız SDK növbəsində çağırılır.
    private static func persistLater(_ events: FileQueue) {
        if events.persistSoon() { return }
        if trailingPersist { return }
        trailingPersist = true
        queue.asyncAfter(deadline: .now() + .seconds(2)) {
            trailingPersist = false
            events.persist()
        }
    }

    private static func schedule(_ core: Core, _ events: FileQueue, _ store: FileStore) {
        // Konfiq dəyişə bilər, ona görə növbəti fasilə hər dəfə yenidən oxunur.
        let interval = DispatchTimeInterval.milliseconds(Int(core.flushIntervalMs))
        queue.asyncAfter(deadline: .now() + interval) {
            store.retrySave()
            core.flush()
            events.persist()
            settleMark()
            schedule(core, events, store)
        }
    }

    #if canImport(UIKit) && !os(watchOS)
    /// `UIApplication.shared` tətbiq genişlənmələrində əlçatan deyil və onlar üçün yığılan kodda
    /// kompilyasiya xətası verir, ona görə obyekt icra vaxtı axtarılır. Genişlənmədə nil qaytarır.
    private static func application() -> UIApplication? {
        if isExtension { return nil }
        let selector = NSSelectorFromString("sharedApplication")
        guard UIApplication.responds(to: selector) else { return nil }
        return UIApplication.perform(selector)?.takeUnretainedValue() as? UIApplication
    }
    #endif

    private static func observeLifecycle() {
        #if canImport(UIKit) && !os(watchOS)
        // Genişlənmədə tətbiqin həyat dövrü bildirişləri gəlmir və arxa fon tapşırığı istənilə bilmir.
        if isExtension { return }
        let center = NotificationCenter.default
        let active = center.addObserver(forName: UIApplication.didBecomeActiveNotification, object: nil, queue: nil) { _ in
            retryBoot()
            // İdarə mərkəzi, icazə pəncərəsi və s. tətbiqi yalnız müvəqqəti qeyri-aktiv edir: bu, yeni açılış deyil.
            openIfNeeded()
        }
        let unlocked = center.addObserver(forName: UIApplication.protectedDataDidBecomeAvailableNotification, object: nil, queue: nil) { _ in
            retryBoot()
        }
        let terminating = center.addObserver(forName: UIApplication.willTerminateNotification, object: nil, queue: nil) { _ in
            // Tətbiq bağlanır: növbə dərhal, çağıran (əsas) axında diskə yazılır. SDK növbəsi gözlənilmir
            // (o, şəbəkə sorğusu ilə məşğul ola bilər); `FileQueue` öz kilidi ilə qorunur.
            lock.lock()
            let events = fileQueue
            lock.unlock()
            events?.persist()
        }
        let background = center.addObserver(forName: UIApplication.didEnterBackgroundNotification, object: nil, queue: nil) { _ in
            needsOpen = true
            // Növbənin göndərilməsi və diskə yazılması üçün sistemdən qısa əlavə vaxt istənilir.
            let app = application()
            var task = UIBackgroundTaskIdentifier.invalid
            let finish = {
                if task != .invalid {
                    app?.endBackgroundTask(task)
                    task = .invalid
                }
            }
            if let app = app {
                task = app.beginBackgroundTask(withName: "az.smartbee.pixel.flush") {
                    // Vaxt bitdi: sistem bu çağırışdan qayıdan kimi tətbiqi dayandırır, ona görə tapşırıq
                    // burada, sinxron bitirilir (çağırış əsas axında gəlir).
                    finish()
                }
            }
            lock.lock()
            let current = core
            let events = fileQueue
            lock.unlock()
            if current == nil {
                // Nüvə hələ başlamayıb (Android ilə eyni qayda): gözləyən ön plan keçidi köhnəlir, arxa fona keçid isə
                // gözləmə siyahısına düşür və nüvə başlayanda icra olunur (sessiyanın vaxtı yazılır, növbə göndərilir).
                launchGate.leftBeforeStart()
                post(kind: kindLifecycle, persistNow: true) { $0.onBackground() }
            }
            queue.async {
                // Göndəriş uzun çəkə bilər: əvvəlcə növbə diskə yazılır ki, sistem tətbiqi dayandırsa da itməsin.
                events?.persist()
                current?.onBackground()
                events?.persist()
                DispatchQueue.main.async { finish() }
            }
        }
        lock.lock()
        observers = [active, unlocked, terminating, background]
        lock.unlock()
        // SDK gec başladıla bilər (məsələn React Native / Flutter-dən): tətbiq artıq aktivdirsə
        // didBecomeActive bir daha gəlməyəcək, ona görə vəziyyət indi oxunur (yalnız əsas axında).
        DispatchQueue.main.async {
            if let app = application(), app.applicationState == .active {
                openIfNeeded()
            }
        }
        #endif
    }
}
